INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61811, 'spa', 'Verdadero en el sentido de veraz, sincero o íntegro, aplicado a personas y su ca', 'Verdadero en el sentido de veraz, sincero o íntegro, aplicado a personas y su carácter, enfatizando la integridad personal más que la exactitud proposicional. Pablo describe su ministerio presentándose ''como veraz'' a pesar de ser llamado engañador (2 Cor 6:8), y en Rom 3:4, Dios mismo es declarado ''veraz'' en su propia naturaleza. La distinción española entre ''verdadero'' y ''veraz'' refleja fielmente esta diferencia semántica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61813, 'spa', 'Genuino, real y definitivo', 'Genuino, real y definitivo: marca lo que es auténticamente divino frente a lo que es derivado, sombra o falsificación. Central en la teología joánica: Jesús como la ''luz verdadera'' (Jn 1:9), el ''pan verdadero'' (Jn 6:32), la ''vid verdadera'' (Jn 15:1), y el Padre como el único ''Dios verdadero'' (Jn 17:3). En Hebreos, el santuario celestial es el ''verdadero tabernáculo'' frente a su copia terrenal (Heb 8:2; 9:24). En Apocalipsis, los juicios de Dios son ''verdaderos y justos'' (Ap 15:3; 16:7; 19:2), y el jinete del caballo blanco es llamado ''Fiel y Verdadero'' (Ap 19:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61819, 'spa', 'Moler grano', 'La actividad de molienda aparece uniformemente: español ''moliendo'', francés ''moudre'', alemán preservando el griego. Ambos pasajes escatológicos presentan el mismo escenario de mujeres en su trabajo diario de molienda. El verbo se conecta con todo el complejo de procesamiento de grano—desde la cosecha hasta la molienda hasta el horneado—que sostenía la vida del antiguo Cercano Oriente, usado aquí para enfatizar lo ordinario del momento cuando ocurre el evento extraordinario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61820, 'spa', 'Adverbio que significa ''verdaderamente, ciertamente, en verdad'', usado para afir', 'Adverbio que significa ''verdaderamente, ciertamente, en verdad'', usado para afirmar la realidad de una declaración o identidad. En el Nuevo Testamento marca confesiones decisivas de fe o reconocimiento: el centurión al pie de la cruz (Mateo 27:54; Marcos 15:39), los discípulos en la barca (Mateo 14:33), así como afirmaciones de hechos verificados (Mateo 26:73; Marcos 14:70). Es consistente en todas las traducciones principales como marcador de certeza genuina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61822, 'spa', 'Pescador de oficio', 'Persona que pesca como medio de vida. Las cinco apariciones neotestamentarias se refieren a los discípulos junto al mar de Galilea: Simón Pedro y Andrés echando redes (Mt 4:18), Jesús prometiendo hacerlos pescadores de hombres (Mt 4:19, Mc 1:17), y pescadores lavando redes a la orilla del lago (Lc 5:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61824, 'spa', 'Acción de salar', 'Se refiere al acto o proceso de salar: preservar, sazonar o purificar. Los dichos de Jesús sobre la sal juegan con múltiples significados: los discípulos como sal preservadora para la tierra, la crisis si esa sal falla y la imposibilidad de volver a salar lo insípido. El uso de Marcos «salado con fuego» es críptico, quizás aludiendo a pruebas como agente purificador o a la práctica sacrificial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61826, 'spa', 'conjunción adversativa', 'Función primaria de ἀλλά como conjunción que marca contraste fuerte, objeción o corrección. Introduce una afirmación que se opone, restringe o corrige lo anterior. Puede traducirse como ''pero'', ''sino'', ''mas'', ''al contrario'', según el contexto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61829, 'spa', 'Cambiar, intercambiar, transformar', 'Cambiar, intercambiar o transformar algo, abarcando tanto el sentido activo de trocar una cosa por otra como el sentido pasivo de ser transformado. En Hch 6:14 la acusación es que Jesús ''cambiará'' las costumbres transmitidas por Moisés. Romanos 1:23 usa la voz activa para el catastrófico intercambio de la gloria divina por imágenes. La voz pasiva en 1 Co 15:51-52 describe la glorificación futura de los creyentes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61834, 'spa', 'De/hacia otro lugar', 'El desplazamiento espacial aparece en las traducciones: español ''a otra parte'' y ''por otro lado'', francés ''d''ailleurs'' (desde otra parte), alemán ''anderswoher'' (desde otro lugar). El contexto de Marcos involucra la extensión del ministerio a otras ciudades, el de Juan involucra el contraste entre medios propios e impropios de acceso. Ambos invocan el concepto de una ubicación o ruta alternativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61836, 'spa', 'Exclamación de alabanza', 'Exclamación litúrgica hebrea transliterada que significa ''¡Alabad a Yah(weh)!'', preservada sin traducir en todos los idiomas de destino, lo cual refleja su condición de clamor universal de adoración. Limitada a las cuatro apariciones en Apocalipsis 19:1-6, marca la celebración celestial culminante del juicio justo de Dios tras la destrucción de Babilonia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61837, 'spa', 'unos a otros', 'Pronombre recíproco en diversos casos (genitivo, dativo, acusativo) que expresa acción mutua o bidireccional entre dos o más personas. Es el elemento estructural detrás de los mandamientos «unos a otros» del Nuevo Testamento: amarse unos a otros (Jn 13:34), servirse mutuamente (Gá 5:13), confesarse unos a otros (Stg 5:16). El español ''unos a otros'' y el alemán ''einander'' captan con fidelidad esta reciprocidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61846, 'spa', 'Saltar o brotar', 'Denota un movimiento repentino y vigoroso de salto o brinco. En Juan, el uso es metafórico: el agua viva como un manantial interior que brota hacia la vida eterna, simbolizando vitalidad continua. En Hechos, describe sanidades físicas dramáticas: una transformación instantánea de la parálisis al salto, al caminar y a la alabanza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61847, 'spa', 'otro, diferente', 'El uso estándar adjetival y sustantivo que significa ''otro'', ''otra'' u ''otros'': una entidad distinta o adicional del mismo tipo. Cubre la gran mayoría de las ocurrencias (155x), incluyendo expresiones como «otro camino» (Mt 2:12), «otra tierra» (Mc 4:5, 7) y «otra mujer» (Mc 10:12). La evidencia multilingüe es consistente: español ''otro/a'', francés ''autre'', alemán ''anderer''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61857, 'spa', 'uno (contraste correlativo)', 'Un uso correlativo especializado en que ἄλλος singulariza a un individuo dentro de un grupo en pares contrastivos («uno decía... otro decía»), funcionando más cerca de ''uno'' que de ''otro''. En Hch 2:12 la multitud se divide y ἄλλος señala una sola voz que pregunta «¿Qué quiere decir esto?». Las glosas se reducen al español ''uno'', distinguiendo este sentido del más amplio de ''otro''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61860, 'spa', 'Un extrano o persona desconocida — la forma sustantivada que designa a alguien f', 'Un extrano o persona desconocida — la forma sustantivada que designa a alguien fuera de la comunidad o relacion reconocida. En Juan 10:5 las ovejas ''no seguiran al extrano'', contrastando la voz desconocida con la llamada familiar del pastor. En Mateo 17:25-26 Jesus distingue a los hijos de los ''extranos'' respecto al impuesto del templo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61861, 'spa', 'Perteneciente a otra persona, que no es propio — usado como adjetivo atributivo ', 'Perteneciente a otra persona, que no es propio — usado como adjetivo atributivo para posesiones, trabajos, siervos o fundamentos que corresponden a otro. La negativa de Pablo a edificar sobre ''fundamento ajeno'' (Ro 15:20) y su advertencia contra participar en ''pecados ajenos'' (1 Ti 5:22) ejemplifican este sentido de propiedad y autoridad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61864, 'spa', 'Extranjero en sentido geografico o nacional — de otro pais o pueblo', 'Extranjero en sentido geografico o nacional — de otro pais o pueblo. Abraham peregrine en tierra ''extranjera'' (Hch 7:6; He 11:9), y los fieles pusieron en fuga a ''ejercitos extranjeros'' (He 11:34). La dimension geografica distingue este sentido: no solo la persona, sino la tierra misma es ἀλλότριος.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61871, 'spa', 'Trillar grano', 'Designa el proceso agrícola literal de separar el grano de las espigas, normalmente mediante bueyes que lo pisan o trabajadores que lo golpean. La cita repetida de Pablo transforma esto en un principio: quienes trabajan merecen participar de la cosecha. La libertad del buey para comer mientras trabaja ilustra la justicia de sostener a los obreros del evangelio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61872, 'spa', 'Irracional o ilógico', 'Denota la ausencia de facultad racional, ya sea en animales mudos o en situaciones ilógicas. El uso epistolar compara a los falsos maestros con bestias brutas que actúan por instinto en vez de razón, destinados a la destrucción. El uso jurídico de Festo lo aplica de otra manera: la irracionalidad de enviar un prisionero sin formular acusaciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61877, 'spa', 'Cadena, grillete (sujeción física) — Una cadena metálica o grillete empleado par', 'Cadena, grillete (sujeción física) — Una cadena metálica o grillete empleado para sujetar físicamente a un prisionero, generalmente atándole las manos o encadenándolo a un guardia. El endemoniado gadareno rompe repetidamente sus cadenas, demostrando un poder sobrenatural sobre la sujeción humana (Mc 5:3-4; Lc 8:29). Las cadenas de Pedro caen milagrosamente al toque del ángel (Hch 12:6-7). Pablo es atado con dos cadenas en Jerusalén (Hch 21:33) y posteriormente se refiere a sus cadenas como testimonio de su entrega al evangelio (Ef 6:20; Flp 1:7, 13-14; 2 Ti 1:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61884, 'spa', 'Nombre propio patronímico', 'Nombre propio de origen arameo (de Chalfay) que designa al padre de uno o más discípulos. Marcos 2:14 identifica a Alfeo como padre de Leví, mientras las listas apostólicas sinópticas y Hechos 1:13 lo nombran como padre de Jacobo. La forma genitiva Ἁλφαίου es patronímica en todas las apariciones, funcionando como marca de identificación más que como referencia independiente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61885, 'spa', 'Era de trillar', 'El término agrícola se preserva: español ''era'', francés ''aire''. Ambos pasajes citan o parafrasean la misma profecía bautismal sobre el juicio mesiánico. La era se convierte en el lugar de separación—un lugar de decisión donde el grano valioso es preservado y la paja sin valor destruida, convirtiéndola en una poderosa imagen del juicio final que distingue a los justos de los malvados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61886, 'spa', 'Zorra literal y figurada', 'Se refiere literalmente a la zorra y metafóricamente a personas astutas o taimadas. El dicho de Jesús sobre la pobreza yuxtapone las guaridas de las zorras con su propia carencia de hogar: incluso animales astutos tienen más seguridad que el Mesías itinerante. La referencia a Herodes destila desprecio: ya sea «ese astuto intrigante» o «esa criatura insignificante», probablemente ambas cosas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61888, 'spa', 'Juntamente, al mismo tiempo — Funciona como adverbio puro que expresa simultanei', 'Juntamente, al mismo tiempo — Funciona como adverbio puro que expresa simultaneidad o participación colectiva sin un sustantivo dependiente. Pablo y los tesalonicenses serán arrebatados ''juntamente'' en las nubes (1 Ts 4:17); la tripulación en Malta soltó las amarras del timón ''al mismo tiempo'' que izaban la vela de proa (Hch 27:40); ''juntamente se desviaron'' (Ro 3:12, citando Sal 14:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61890, 'spa', 'Junto con — Funciona como preposición que rige un complemento explícito o un mar', 'Junto con — Funciona como preposición que rige un complemento explícito o un marcador temporal. En Mt 13:29, el amo advierte contra arrancar la cizaña ''junto con'' (ἅμα) el trigo, donde la palabra rige un objeto dativo implícito. En Mt 20:1, ἅμα πρωΐ significa ''de madrugada'' (literalmente ''junto con el alba''), un uso temporal-preposicional que indica el comienzo del día.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61894, 'spa', 'Pecar, cometer pecado — el verbo en todas sus formas activas finitas (indicativo', 'Pecar, cometer pecado — el verbo en todas sus formas activas finitas (indicativo, subjuntivo, imperativo), que abarca el acto general de pecar contra Dios, contra otra persona o contra la propia conciencia. Jesús enseña cómo confrontar a un hermano ''si peca contra ti'' (Mt 18:15, 21), el hijo pródigo ensaya su confesión (Lc 15:18, 21) y Pablo declara universalmente que ''todos pecaron'' (Ro 3:23).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61898, 'spa', 'El que peca, pecando — la forma participial que funciona como sustantivo o adjet', 'El que peca, pecando — la forma participial que funciona como sustantivo o adjetivo para caracterizar a una persona o grupo por su pecado. Pablo argumenta que la muerte reinó aun sobre los que no habían ''pecado a semejanza de la transgresión de Adán'' (Ro 5:14), que por el pecado de un solo hombre vino el juicio (Ro 5:16), y que los ancianos que pecan deben ser reprendidos públicamente (1 Ti 5:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61908, 'spa', 'Pecar (infinitivo de propósito) — el infinitivo que expresa el concepto de pecar', 'Pecar (infinitivo de propósito) — el infinitivo que expresa el concepto de pecar como posibilidad abstracta u orientación, más que un acto pecaminoso específico. Juan escribe que el nacido de Dios ''no puede pecar'' (1 Jn 3:9), usando el infinitivo para nombrar la capacidad misma o la disposición hacia el pecado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61912, 'spa', 'Acto pecaminoso concreto', 'Una acción pecaminosa concreta, distinguida del principio abstracto del pecado (hamartia). Marcos 3:28-29 lo empareja con ''blasfemias'' para enumerar ofensas perdonables; Romanos 3:25 lo emplea para transgresiones pasadas que Dios pasó por alto; 1 Corintios 6:18 especifica un pecado cometido contra el propio cuerpo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61913, 'spa', 'pecado, transgresión', 'El término fundamental del Nuevo Testamento para la falta moral y espiritual ante Dios, que abarca tanto la transgresión deliberada como la condición de caída. Usado 173 veces en todos los casos y números, va desde actos pecaminosos concretos (Mt 12:31) hasta el pecado como poder personificado que reina sobre la humanidad (Ro 5:21). Las traducciones en las 43 lenguas convergen en un único equivalente, subrayando su carácter semántico unívoco.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61920, 'spa', 'Pecador, persona pecaminosa — persona caracterizada por el pecado, usado como ad', 'Pecador, persona pecaminosa — persona caracterizada por el pecado, usado como adjetivo atributivo (''pecaminoso'') y como sustantivo (''un pecador''), con estigma social en los Evangelios y peso teológico en las Epístolas. La comunión de mesa de Jesús con ''pecadores'' (Mt 9:10-13; Lc 15:1-2) provoca controversia y define su misión. La ''mujer pecadora'' de Lucas (7:37) y el publicano que clama ''a mí, pecador'' (18:13) emplean el término en escenas de profunda carga emocional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61928, 'spa', 'Pacífico, no contencioso', 'La cualidad no contenciosa aparece consistentemente: español ''pacíficos'' y ''no contencioso'', francés preservando el griego, alemán ''friedfertig'' (dispuesto a la paz). Ambos pasajes paulinos lo incluyen entre las virtudes requeridas de líderes cristianos y todos los creyentes. El término contrasta con comportamiento pendenciero, violento o contencioso, llamando en cambio a una disposición pacificadora.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61931, 'spa', 'Descuidar, desatender', 'Ser negligente o descuidado con algo que merece atención, desde la indiferencia casual hasta la desatención espiritual culpable. Mateo 22:5 describe a invitados que ignoran una invitación real de bodas; 1 Timoteo 4:14 advierte a Timoteo que no descuide su don espiritual; Hebreos 2:3 escala al descuido de la salvación misma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61932, 'spa', 'Irreprensible, sin falta', 'Sin culpa ni defecto, más allá de toda crítica legítima. Describe la conducta intachable de Zacarías y Elisabet (Lc 1:6), la justicia farisaica de Pablo (Fil 3:6) y la santidad escatológica de los creyentes (1 Ts 3:13). En Hebreos 8:7 se aplica al primer pacto mismo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61933, 'spa', 'Manera irreprochable', 'La manera irreprochable aparece uniformemente: español ''irreprensiblemente'', francés preservando el griego, alemán ''untadelig'' (sin tacha). Primera Tesalonicenses 2:10 lo aplica a la conducta apostólica pasada, mientras que 5:23 mira hacia la irreprochabilidad escatológica. Ambos contextos enfatizan una conducta moral que no es solo buena sino más allá de cualquier crítica legítima, reflejando la santidad integral que Dios requiere.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61934, 'spa', 'Libre de preocupaciones', 'El tema de la libertad de preocupación atraviesa las traducciones: español ''sin preocupaciones'', francés ''sans souci'', alemán preservando el griego. El contexto de Mateo implica eliminar el peligro legal, mientras que el de Pablo aborda el enfoque espiritual libre de lealtades divididas. Ambos implican remover causas de ansiedad, aunque con fines diferentes—uno para proteger de problemas, el otro para permitir devoción sin distracciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61935, 'spa', 'Carácter inmutable', 'El tema de inmutabilidad es consistente: español ''inmutable/inmutables'', francés ''immuable'', alemán ''unveränderlich'' (inmutable). Ambos versículos ocurren dentro de un solo argumento sobre la certeza de la promesa de Dios. El trasfondo filosófico clásico del conocimiento inmutable y el destino se aplica aquí a la confiabilidad del compromiso divino—el carácter de Dios asegura que sus promesas no pueden ser revocadas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61937, 'spa', 'Calidad irrevocable', 'La cualidad irrevocable aparece en todos los idiomas: español ''irrevocables'' y ''sin arrepentimiento'', francés ''sans repentir'', alemán ''ohne Reue'' (sin pesar/arrepentimiento). Romanos lo aplica a los dones divinos que Dios no revocará, mientras que 2 Corintios describe el arrepentimiento humano del que uno nunca se arrepentirá. Ambos contextos valoran la permanencia y la decisión—los compromisos de Dios no cambian, y el arrepentimiento genuino no se lamenta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61939, 'spa', 'Más allá de límites', 'El tema de desmesura aparece: español ''sin medida'', francés ''sans mesure'', alemán ''übermässig'' (excesivo). Ambos versículos ocurren en la defensa de Pablo de su apostolado contra críticos en Corinto. La imagen implica respetar límites medidos—Pablo se gloriará solo dentro de la esfera que Dios midió para él, sin reclamar crédito por el trabajo de otros en regiones más allá de su territorio asignado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61940, 'spa', 'amén', 'Partícula de origen hebreo que expresa afirmación solemne, verdad y asentimiento. En contextos litúrgicos cierra oraciones y doxologías como un «así sea» congregacional (1 Co 14:16; Ap 5:14). De modo distintivo, Jesús la usa para abrir declaraciones —«Amén os digo» (Mt 5:18; duplicada en Jn 1:51)—, fórmula sin paralelo rabínico que reivindica autoridad intrínseca. La palabra cruza todas las traducciones sin alteración.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61946, 'spa', 'Puro, sin mancha', 'Libre de toda mancha o impureza moral, puro en el sentido más pleno. En español se distingue entre ''incontaminada'' y ''sin mancha'', reflejando las dimensiones ritual y moral. Se aplica al carácter sacerdotal de Cristo (Heb 7:26), a la fidelidad conyugal (Heb 13:4), a la religión pura (Stg 1:27) y a la herencia imperecedera (1 Pe 1:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61947, 'spa', 'Ancestro mesiánico', 'Identifica a un ancestro específico en el linaje mesiánico: padre de Naasón, quien dirigió a Judá en el censo de Moisés y, según la tradición rabínica, fue el primero en entrar al Mar Rojo. Su doble aparición en Mateo 1:4 refleja la declinación griega del nombre hebreo indeclinable. Su inclusión subraya la conexión de Jesús con la realeza de la tribu de Judá.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61948, 'spa', 'Arena, material granular', 'Arena, material granular fino de costas y desiertos, empleado literal y figuradamente. Jesús la usa para el cimiento inestable de un constructor insensato (Mt 7:26). Pablo y Hebreos recurren al tropo de la arena del mar para la descendencia innumerable de Abraham (Ro 9:27, Heb 11:12). En Apocalipsis, el dragón se posiciona sobre ella.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61949, 'spa', 'Cordero sacrificial cristológico', 'Un cordero visto como figura sacrificial o cristológica, no meramente una oveja joven. En español se distingue el ''Cordero'' en mayúscula (título cristológico) del ''cordero'' en minúscula (animal genérico), distinción visible en las cuatro apariciones neotestamentarias. Todas las ocurrencias del NT señalan a Jesús como cumplimiento del cordero pascual y del siervo sufriente de Isaías 53.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61951, 'spa', 'Vid, parra', 'La vid como planta cultivada que produce fruto para el vino, empleada tanto en su sentido agricola literal como en una rica metafora teologica. En la ultima cena (Mt 26:29; Mr 14:25; Lc 22:18), ''el fruto de la vid'' se refiere directamente al vino. En Jn 15:1-5, Jesus se identifica como ''la vid verdadera'', desarrollando una alegoria extensa de union espiritual, poda y fecundidad. En Ap 14:18-19, la imagen se traslada al juicio escatologico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61954, 'spa', 'Un terreno cultivado de vides, usado literal y parabólicamente como imagen de lo', 'Un terreno cultivado de vides, usado literal y parabólicamente como imagen de los tratos de Dios con la humanidad. Aparece en la parábola de los obreros (Mt 20:1-8), los labradores malvados (Mt 21:33-41; Mc 12:1-9; Lc 20:9-16), y el argumento de Pablo sobre los derechos apostólicos (1 Cor 9:7). La tradición de la LXX, especialmente el Cántico de la Viña de Isaías 5, aporta una profunda resonancia de pacto a cada uso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61959, 'spa', 'Vestir, arropar', 'Poner ropa sobre alguien, vestir o engalanar a una persona o cosa con vestiduras. Las formas activas en Mateo 6:30 y Lucas 12:28 describen a Dios vistiendo la hierba con esplendor; el participio pasivo en Mateo 11:8 y Lucas 7:25 retrata a una persona ataviada con vestiduras lujosas, en contraste con la sencillez ascética.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61962, 'spa', 'Adjetivo o pronombre que significa ''ambos'', indicando dos personas, grupos o cos', 'Adjetivo o pronombre que significa ''ambos'', indicando dos personas, grupos o cosas tomados juntos. Usado en parabolas para emparejar resultados (ambos odres preservados, Mt 9:17; tanto el trigo como la cizana dejados crecer, Mt 13:30; tanto guias ciegos como seguidores cayendo, Mt 15:14). Pablo lo emplea con fuerza teologica en Efesios 2:14-18, donde Cristo reconcilia a ''ambos'', judio y gentil, en una nueva humanidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61966, 'spa', 'Irreprochable, sin mancha', 'Sin mancha, irreprochable, inmaculado: describe pureza moral o ritual y ausencia de defecto. Enraizado en el lenguaje sacrificial donde las victimas debian ser fisicamente perfectas, el Nuevo Testamento transfiere esto a la realidad espiritual: creyentes escogidos para ser ''santos e irreprochables'' ante Dios (Ef 1:4), la iglesia presentada ''sin mancha'' (Ef 5:27), hijos de Dios irreprochables que resplandecen como luminares (Fil 2:15), y los redimidos guardados sin caida (Jud 1:24).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61971, 'spa', 'Especia aromatica (amomon)', 'Especia fragante o sustancia aromatica: la planta amomon (probablemente Amomum cardamomum o una especie afin), enumerada entre las mercancias de lujo en el lamento por la caida de Babilonia (Ap 18:13). Este uso nominal no guarda relacion semantica con el adjetivo ''irreprochable'' y probablemente representa una entrada homografa o variante textual, ya que algunos manuscritos registran amomon como una palabra distinta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61972, 'spa', 'Figura genealógica', 'Designa a figuras genealógicas que portan este nombre, especialmente Amón rey de Judá, hijo del impío Manasés y padre del reformador Josías (2 Reyes 21). La genealogía de Mateo lo incluye entre los ancestros reales de Jesús a pesar de su breve y perverso reinado. El Amós de Lucas podría ser un ancestro distinto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61973, 'spa', 'generalizador indefinido', 'El grupo más numeroso con 89 ocurrencias, donde ἄν se combina con pronombres y adverbios relativos para formar expresiones indefinidas universales: ὃς ἄν («quienquiera»), ὃ ἄν («lo que sea»), ὅπου ἄν («dondequiera»). En Mt 16:25, «el que [ὃς ἄν] quiera salvar su vida, la perderá», la partícula transforma un ''quien'' específico en un ''quienquiera'' universal. El español emplea el sufijo -quiera para este efecto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61976, 'spa', 'condicional contrafáctico', 'Marcador condicional contrafáctico en 32 ocurrencias, donde ἄν aparece en la apódosis de condiciones contrarias a los hechos, normalmente con tiempos indicativos pasados. En Mt 11:21, «si en Tiro se hubieran hecho los milagros... ya se habrían arrepentido», la partícula señala que el arrepentimiento no ocurrió realmente. El español usa el condicional compuesto (habrían) para expresar esta irrealidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61979, 'spa', 'potencial o dubitativo', 'Sentido potencial o dubitativo en 23 ocurrencias, expresando lo que podría, pudiera o acaso sucedería. En Lc 1:62 hacían señas a Zacarías sobre cómo «querría [ἄν]» llamar al niño; en Hch 8:31 el etíope pregunta «¿cómo podría [ἄν] entender si alguien no me guía?». El español recurre al condicional simple o al subjuntivo para captar esta cualidad tentativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61981, 'spa', 'contingencia temporal', 'Contingencia temporal en 11 ocurrencias, donde ἄν se combina con conjunciones temporales (ὅταν, ἐπάν, ἡνίκα) para marcar un evento como indefinido en su momento: «siempre que», «tan pronto como», «en cualquier momento que». En Hch 2:35, «hasta que ponga a tus enemigos por estrado», el límite temporal se establece pero el instante exacto queda contingente. El español emplea «tan pronto como» o «siempre que».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (61983, 'spa', 'marcador de subjuntivo', 'Marcador de cláusula subjuntiva en 11 ocurrencias, donde ἄν funciona como señal gramatical casi intraducible en cláusulas de propósito, resultado o condición, aportando fuerza modal o hipotética sin contenido léxico propio. En He 1:13 y He 4:8 la partícula aparece en cláusulas subordinadas con función estructural más que semántica, marcándolas como no asertivas. La mayoría de las traducciones la absorben en la morfología verbal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62005, 'spa', 'Uso distributivo con numerales o sustantivos', 'Uso distributivo con numerales o sustantivos: ''cada uno, por cabeza, de a''. El patron ἀνά + numero aparece en el envio de discipulos ''de dos en dos'' (Lc 10:1), el pago de un denario cada uno (Mt 20:9-10), y las seis tinajas que contenian ''dos o tres medidas cada una'' (Jn 2:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62007, 'spa', 'Preposicion espacial que significa ''entre, en medio de, por''', 'Preposicion espacial que significa ''entre, en medio de, por''. El enemigo siembra cizana ''entre'' el trigo (Mt 13:25), Pablo pregunta si no hay un sabio ''entre'' los corintios (1 Co 6:5), y el Cordero guia a los suyos ''a'' fuentes de aguas vivas (Ap 7:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62010, 'spa', 'Frase adverbial secuencial ἀνὰ μέρος, ''por turno, uno a la vez'', que rige el hab', 'Frase adverbial secuencial ἀνὰ μέρος, ''por turno, uno a la vez'', que rige el hablar ordenado de lenguas en la asamblea corintia (1 Co 14:27). Esta unica ocurrencia forma una expresion fija mas que un uso preposicional libre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62012, 'spa', 'Escaleras arquitectónicas', 'El término arquitectónico se preserva: español ''gradas'' (escalones), francés ''marche'', alemán conserva el griego. Ambas referencias describen la misma escalinata durante el mismo incidente dramático. Las escaleras marcan el límite entre el espacio sagrado judío abajo y la autoridad militar romana arriba, convirtiéndose en el lugar donde Pablo se dirige a la multitud judía antes de comenzar su viaje de encarcelamiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62013, 'spa', 'subir, ascender', 'Subir o ascender físicamente — el sentido abrumadoramente dominante con 75 ocurrencias, que abarca viajar a terreno más alto, subir montañas, ir a Jerusalén y entrar en aposentos altos. Jesús sube a un monte a orar (Mt 14:23), sale del agua bautismal (Mt 3:16) y «sube a Jerusalén» para la última Pascua (Mt 20:17). El uso de peregrinación a Jerusalén es especialmente significativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62024, 'spa', 'embarcar, abordar', 'Embarcar, subir a una nave — una única ocurrencia en Hch 21:6 donde Pablo y sus compañeros «subieron» a un barco. Aquí el movimiento ascendente va desde un muelle o costa hasta la cubierta de una embarcación. Se trata de una aplicación náutica especializada del verbo básico «subir».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62031, 'spa', 'surgir, venir al corazón', 'Surgir, venir al corazón o a la mente — una única ocurrencia en Lc 24:38 donde Jesús pregunta a los discípulos sobresaltados «¿Por qué surgen dudas en vuestro corazón?». Aquí ἀναβαίνω se usa metafóricamente para pensamientos o emociones que «suben» dentro de una persona, un ascenso psicológico interior en vez de movimiento físico ascendente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62037, 'spa', 'crecer, brotar', 'Crecer, brotar — referido a plantas que germinan y aumentan de tamaño, con 2 ocurrencias en las parábolas agrícolas de Marcos. En Mr 4:8 la semilla cae en buena tierra y «crece» dando fruto; en Mr 4:32 la semilla de mostaza «crece» y se convierte en la mayor de las hortalizas. La metáfora del crecimiento biológico extiende la semántica de movimiento ascendente de ἀναβαίνω al dominio orgánico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62039, 'spa', 'ascender al cielo', 'Ascender al cielo — 3 ocurrencias de denso peso cristológico. En Jn 20:17 el Jesús resucitado dice a María Magdalena «Aún no he subido a mi Padre» y «Subo a mi Padre», y en Ef 4:10 Pablo declara «El que descendió es el mismo que también subió por encima de todos los cielos». No se trata simplemente de subir una cuesta, sino de pasar del ámbito terrenal a la presencia divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62046, 'spa', 'Dirigir físicamente la mirada hacia arriba, alzar los ojos hacia el cielo o haci', 'Dirigir físicamente la mirada hacia arriba, alzar los ojos hacia el cielo o hacia el entorno. En español, ''alzando la vista'' y ''habiendo mirado arriba'' distinguen este sentido del de sanidad. Jesús mira hacia arriba antes de multiplicar los panes (Mt 14:19; Mc 6:41), mira al cielo antes de sanar (Mc 7:34), y tras sanar parcialmente a un ciego, el hombre ''mira arriba'' y ve a las personas como árboles que caminan (Mc 8:24).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62048, 'spa', 'Recobrar o recibir la capacidad de ver tras la ceguera, ya sea por sanidad milag', 'Recobrar o recibir la capacidad de ver tras la ceguera, ya sea por sanidad milagrosa o restauración divina. En español, ''recobrar la vista'' y ''recibió la vista'' marcan consistentemente este sentido de vista recuperada. Es central para las credenciales mesiánicas de Jesús (Mt 11:5; Lc 7:22) y se dramatiza en sanidades individuales (Mt 20:34; Mc 10:51-52; Lc 18:42; Jn 9:11, 15, 18). La ceguera y recuperación de Pablo (Hch 9:12, 17-18) extiende el motivo más allá del ministerio terrenal de Jesús.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62063, 'spa', 'Comunicar informacion de manera deliberada a una audiencia, ya sea informando so', 'Comunicar informacion de manera deliberada a una audiencia, ya sea informando sobre eventos ocurridos, declarando verdades teologicas o anunciando lo que ha de venir. En Juan 16:13-15, el Espiritu ''anunciara'' realidades futuras, dandole al verbo un matiz profetico-revelador. En Hechos y las Epistolas, describe el informe misionero (Hch 14:27; 20:20) y la proclamacion fundacional (1 Jn 1:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62072, 'spa', 'Regeneración espiritual', 'El tema de regeneración aparece consistentemente: español ''habiendo regenerado'' y ''habiendo sido regenerados'', francés preserva el griego, alemán ''wiedergeboren'' (nacido de nuevo). Ambas referencias en 1 Pedro conectan el nuevo nacimiento con la misericordia de Dios, la resurrección de Cristo y la palabra eterna. El verbo captura la novedad radical de la conversión cristiana—no mera mejora sino nueva creación, un nacimiento completamente nuevo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62073, 'spa', 'Leer — lectura activa de un texto escrito, ya sea Escritura, carta o documento, ', 'Leer — lectura activa de un texto escrito, ya sea Escritura, carta o documento, ya sea en privado o en público. El retórico ''¿no habéis leído?'' de Jesús (Mt 12:3, 5; 21:42) presupone un compromiso personal con el texto. Abarca el estudio, la cita y la lectura personal de las Escrituras.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62074, 'spa', 'Ser leído en voz alta — voz pasiva', 'Ser leído en voz alta — voz pasiva: un texto que se lee en voz alta ante otros, especialmente en el culto congregacional o la asamblea pública. Pablo instruye que su carta sea leída (ἀναγινωσκομένη) entre las iglesias (Col 4:16), y Moisés es leído en voz alta cada sábado (Hch 15:21). El español distingue claramente la pasiva (''es leído'', ''leída'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62090, 'spa', 'Obligar, forzar (activo)', 'Compulsion activa: presionar, instar o forzar a alguien a hacer algo, ya sea mediante autoridad, presion social o persuasion energica. Jesus ''obligo'' (ἠνάγκασεν) a los discipulos a subir a la barca (Mt 14:22; Mr 6:45), y el senor ordena al siervo ''obligar'' a la gente de los caminos a entrar (Lc 14:23). Los verbos espanoles ''obligar'' y ''forzar'' convergen en este sentido de compulsion directa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62091, 'spa', 'Ser obligado (pasivo)', 'Compulsion pasiva: ser forzado o constreniido por las circunstancias o por la autoridad de otro. Pablo fue ''obligado'' a apelar al Cesar (Hch 28:19), y Tito, aunque era griego, no fue ''obligado'' a circuncidarse (Ga 2:3). La voz pasiva traslada el enfoque a quien experimenta la presion en vez de a quien la ejerce, y la expresion espanola ''fue obligado'' refleja esta perspectiva del receptor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62098, 'spa', 'Necesario, esencial', 'Necesario, esencial o indispensable: aquello que las circunstancias o el proposito requieren. Pablo lo emplea en argumentos sobre la necesidad divina (Hch 13:46, la palabra debe ir primero a los judios), la interdependencia eclesial (1 Co 12:22, los miembros mas debiles son ''mas necesarios''), la obligacion pastoral (Fil 1:24) y disposiciones practicas (2 Co 9:5; Fil 2:25; Tit 3:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62101, 'spa', 'Cercano, intimo', 'Dicho de personas: cercano, intimo, unido por lazos de parentesco o amistad profunda. En Hch 10:24, Cornelio convoca a sus parientes y a sus ἀναγκαίους φίλους, amigos tan cercanos que le son ''necesarios''. El desarrollo semantico de la compulsion externa al vinculo intimo es paralelo al latin ''necessarius'', que igualmente significa tanto ''necesario'' como ''estrechamente ligado''. El espanol ''intimos'' capta esta calidez relacional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62104, 'spa', 'Necesidad, compulsión o constricción ineludible — el estado de algo que es reque', 'Necesidad, compulsión o constricción ineludible — el estado de algo que es requerido u obligatorio. Abarca la necesidad divina (Mateo 18:7, ''es necesario que vengan los tropiezos''), la compulsión moral (Romanos 13:5, sujeción ''por causa de la conciencia''), la obligación práctica (Lucas 14:18, ''tengo necesidad de ir''), y el deber apostólico (1 Corintios 9:16, ''me es impuesta necesidad''). El español ''necesidad'' captura fielmente este sentido de obligación ineludible.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62107, 'spa', 'Angustia, adversidad o calamidad — la presión de circunstancias extremas', 'Angustia, adversidad o calamidad — la presión de circunstancias extremas. En Lucas 21:23, ἀνάγκη describe la gran tribulación que vendrá sobre la tierra junto con la ira. Pablo la enumera entre sus sufrimientos apostólicos: ''en necesidades, en angustias'' (2 Corintios 6:4), ''en necesidades... en persecuciones'' (2 Corintios 12:10). El español ''angustia'' y el emparejamiento contextual con θλῖψις (tribulación) en 1 Tesalonicenses 3:7 distinguen este registro más sombrío.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62116, 'spa', 'Lectura pública', 'Designa el acto de leer, particularmente la lectura pública de las Escrituras en contextos de culto. Lucas establece el patrón sinagogal: se lee en voz alta la Torá y los Profetas, y luego se invita a la exposición. La imagen paulina del velo (2 Cor 3:14) ilustra una lectura sin comprensión: los ojos en el texto pero el corazón velado. El encargo a Timoteo incluye la lectura pública como deber pastoral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62117, 'spa', 'El sentido dominante en el Nuevo Testamento', 'El sentido dominante en el Nuevo Testamento: hacerse a la mar, zarpar, partir en barco. Catorce de veintitrés ocurrencias describen partidas marítimas en Lucas-Hechos, donde el verbo funciona casi como fórmula para avanzar la narrativa de viaje (Hch 13:13; 16:11; 27:21). En español, ''zarpar'' captura el sabor náutico técnico. El componente de ''ascenso'' refleja la percepción antigua del movimiento mar adentro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62120, 'spa', 'Movimiento físico ascendente', 'Movimiento físico ascendente: conducir o llevar a alguien a un lugar más elevado o ante una asamblea. Jesús es llevado por el Espíritu al desierto (Mt 4:1), llevado a un monte alto (Lc 4:5), o un niño es presentado en el templo (Lc 2:22). En Hechos 9:39, Pedro es llevado al piso superior donde yacía la difunta Tabita. La fuerza direccional de ἀνά permanece literal aquí: ascenso en el espacio físico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62122, 'spa', 'Una extensión teológicamente cargada', 'Una extensión teológicamente cargada: hacer subir de entre los muertos. Romanos 10:7 pregunta ''¿Quién descenderá al abismo para hacer subir a Cristo?'' y Hebreos 13:20 celebra a Dios que ''hizo subir de entre los muertos a nuestro Señor Jesús.'' El movimiento ascendente trasciende la geografía para abarcar el límite cósmico entre la muerte y la vida. Este sentido de resurrección porta el peso teológico más profundo del verbo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62124, 'spa', 'Ofrecer o presentar como acto sacrificial', 'Ofrecer o presentar como acto sacrificial. En Hechos 7:41, los israelitas ''ofrecieron sacrificio'' al becerro de oro. El movimiento ascendente aquí es cultual: elevar una ofrenda hacia la deidad. Aunque solo una ocurrencia porta este sentido en el Nuevo Testamento, conecta con el uso más amplio de ἀνάγω en la Septuaginta para presentar ofrendas ante Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62133, 'spa', 'Nombramiento divino', 'El tema del nombramiento aparece: español ''designó'' y ''muestra'', francés ''montrer'', alemán preserva el griego. Lucas 10 involucra el nombramiento autoritativo de Jesús de los setenta, mientras Hechos 1 busca revelación divina de la elección de Dios entre dos hombres calificados. Ambos contextos involucran dar a conocer la selección de Dios para el servicio ministerial, ya sea mediante designación directa (Lucas) o petición en oración (Hechos).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62135, 'spa', 'Recepción hospitalaria', 'El tema de recepción aparece: español ''habiendo recibido'' y ''habiéndonos acogido'', francés ''recevoir'', alemán ''annehmen'' (aceptar/recibir). Hechos claramente involucra hospitalidad generosa hacia extraños, mientras Hebreos conecta la obediencia de Abraham con su previa recepción de las promesas de Dios. Ambos contextos involucran aceptar o acoger lo que se ofrece—ya sean personas (Hechos) o promesas divinas (Hebreos).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62137, 'spa', 'Revivir, volver a vivir', 'El tema de revivir aparece: español ''revivió'', francés ''revivre'', alemán ''wieder lebendig werden'' (volver a estar vivo). El contexto del hijo pródigo celebra el regreso de la muerte espiritual, mientras Romanos describe el despertar mortal del pecado cuando la ley reveló su verdadera naturaleza. Ambos involucran la transición de la falta de vida a la existencia activa, ya sea positiva (restauración del hijo) o negativa (activación mortífera del pecado).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62138, 'spa', 'Búsqueda diligente', 'Denota una búsqueda deliberada y cuidadosa. El relato lucano de la infancia muestra la preocupación paterna: un día entero de camino antes de notar la ausencia de Jesús, seguido de una búsqueda ansiosa entre la caravana. La búsqueda de Saulo por parte de Bernabé revela intención estratégica: encontrar a la persona adecuada para la iglesia de Antioquía.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62142, 'spa', 'Maldición, anatema', 'Pronunciamiento solemne de maldición divina o consagración a la destrucción, aplicado tanto a personas como al acto mismo de maldecir. En Hch 23:14 los conspiradores se comprometen ''con maldición'' (ἀναθέματι), mostrando la función de juramento vinculante. Romanos 9:3 lo usa como autoimprecación: Pablo aceptaría ser anatema, separado de Cristo, por causa de Israel. En 1 Co 12:3, ''Jesús es anatema'' es la confesión falsa definitiva, contrastada con ''Jesús es Señor''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62145, 'spa', 'Maldecirse bajo juramento', 'Ponerse a sí mismo o a otros bajo una maldición solemne (anatema), invocando castigo divino por el incumplimiento de un juramento. En español ''maldecir/maldijimos'' y en francés ''prononcer un anathème'' resaltan la naturaleza autoimprecatoria del acto. Marcos 14:71 describe a Pedro maldiciendo durante su negación; Hechos 23:12-21 relata a conspiradores que se obligaron bajo maldición, un compromiso religiosamente vinculante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62146, 'spa', 'Observación reflexiva', 'El tema de observación cuidadosa aparece con traducciones españolas ''considerando'' y ''observando'', francés ''considérer'', alemán ''betrachten'' (contemplar). Hechos presenta el reconocimiento estratégico de Pablo sobre la religión ateniense para encontrar un punto de entrada al evangelio, mientras Hebreos llama al examen reflexivo de las vidas de los líderes para inspirar imitación. Ambos requieren más que una mirada casual: atención reflexiva que concluye.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62150, 'spa', 'Matar, ejecutar o dar muerte por medios violentos o judiciales, el sentido domin', 'Matar, ejecutar o dar muerte por medios violentos o judiciales, el sentido dominante en el Nuevo Testamento. Solo en Hechos se usa más de una docena de veces para ejecuciones y asesinatos (Hch 2:23; 5:33; 7:28; 12:2; 23:15). En español, ''matar/mataron'' traduce consistentemente este sentido letal. La forma pasiva ''ser ejecutado'' aparece en contextos de martirio y persecución.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62161, 'spa', 'Quitar, remover o abolir algo de su lugar o estado establecido', 'Quitar, remover o abolir algo de su lugar o estado establecido. En Hebreos 10:9, Cristo ''quita lo primero [el pacto] para establecer lo segundo,'' un uso teológico donde la remoción sirve a un propósito redentor. El sentido clásico griego de anular leyes o abrogar límites subyace a este uso. En español, ''quita'' captura el carácter no violento de esta acepción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62165, 'spa', 'Tomar o recoger, especialmente a un niño para adoptarlo o criarlo, el sentido má', 'Tomar o recoger, especialmente a un niño para adoptarlo o criarlo, el sentido más antiguo del compuesto (ἀνά + αἱρέω, ''levantar''). Hechos 7:21 preserva este significado arcaico: cuando Moisés fue expuesto, la hija del faraón ''lo tomó y lo crió como su propio hijo.'' En español, ''tomó'' y el contexto de crianza distinguen este sentido del sentido violento principal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62166, 'spa', 'Libre de culpa', 'El tema de inocencia aparece consistentemente: español ''inocentes'' y ''sin culpa'', francés ''innocent'', alemán preservando el griego. Ambos versículos defienden a personas realizando trabajo necesario o legítimo contra acusaciones de transgresión. Jesús argumenta de mayor a menor: si los sacerdotes están sin culpa trabajando en sábado, cuánto más sus discípulos recogiendo espigas para satisfacer el hambre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62167, 'spa', 'Incorporarse (resurrección)', 'La acción de incorporarse aparece uniformemente: español ''se sentó'', francés ''s''asseoir'' (sentarse) y ''se relever'' (incorporarse), alemán preservando el griego. Ambas narraciones de resurrección usan el mismo verbo para el mismo momento crucial: la transición de la quietud de la muerte al movimiento de la vida. La acción es tanto literal como profundamente simbólica, manifestando la restauración de vida mediante la palabra de Jesús y su apóstol.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62169, 'spa', 'Renovación progresiva', 'El tema de renovación aparece consistentemente: español ''se renueva'' y ''que se renueva'', francés ''renouveler'', alemán ''erneuern'' (renovar). El uso de Pablo en ambos pasajes emplea participios presentes pasivos, enfatizando acción divina continua. Segunda Corintios resalta renovación interior diaria a pesar del deterioro exterior, mientras Colosenses conecta renovación con conocimiento y conformidad a la imagen de Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62170, 'spa', 'Renovación transformadora', 'El concepto de renovación aparece uniformemente: español ''renovación'', francés ''renouvellement'', alemán ''Erneuerung'' (renovación). Romanos lo aplica específicamente a la transformación de la mente, mientras Tito lo presenta como la obra comprehensiva del Espíritu. Ambos contextos atribuyen renovación a agencia divina: no es superación personal sino el poder recreador de Dios restaurando a los creyentes hacia su propósito y naturaleza previstos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62171, 'spa', 'descubrir, revelar', 'El tema del descubrimiento aparece: español ''con descubierto'' y ''siendo descubierto,'' francés ''dévoiler,'' alemán ''aufdecken'' (descubrir). Ambos versículos pertenecen a la metáfora sostenida de Pablo sobre velos y revelación. El acto literal de quitar una cubierta se convierte en una imagen poderosa de iluminación espiritual—solo cuando el velo se levanta en Cristo pueden las personas ver verdaderamente la gloria de Dios y ser transformadas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62172, 'spa', 'Volver o regresar', 'Retornar a un lugar del que se partió previamente, doblando el curso en sentido inverso. Mateo 2:12 relata a los Magos regresando por otro camino; Lucas 10:6 usa el verbo metafóricamente para la paz que retorna al emisor; Hechos 18:21 registra la promesa de Pablo de volver; Hebreos 11:15 destaca la renuncia de los patriarcas a regresar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62173, 'spa', 'Reclinarse a la mesa en la postura antigua de acostarse de lado sobre un divano,', 'Reclinarse a la mesa en la postura antigua de acostarse de lado sobre un divano, apoyado en el codo — la practica estandar grecorromana y judia para comidas formales. Las 14 apariciones en el NT describen escenas de comensalidad: el banquete con pecadores (Mt 9:10), la parabola de las bodas (Mt 22:10-11), la uncion en Betania (Mt 26:7) y la Ultima Cena (Mt 26:20). El verbo funciona como marcador de comunion de mesa y hospitalidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62181, 'spa', 'resumir, unificar', 'La función de resumir aparece: español ''se resume'' y ''reunir bajo una cabeza,'' francés ''résumer,'' alemán ''zusammenfassen'' (sintetizar). Romanos lo aplica a condensación ética—muchas leyes unificadas en el amor. Efesios presenta unificación cósmica—toda la creación reunida bajo el señorío de Cristo. Ambos implican traer multiplicidad a la unidad mediante un principio comprehensivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62182, 'spa', 'Reclinarse (intransitivo)', 'Reclinarse a la mesa, especialmente para una comida festiva o comunitaria (intransitivo/pasivo). En Mt 8:11 y Lc 13:29, los fieles de oriente y occidente ''se reclinarán'' en el banquete escatológico con Abraham, Isaac y Jacob, una imagen vívida de inclusión en el reino. Mt 14:19 lo usa para describir a las multitudes sentándose antes de la alimentación milagrosa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62183, 'spa', 'Acostar, hacer reclinar (transitivo)', 'Hacer que alguien se recline o acostar a alguien (transitivo/causativo). En Lc 2:7, María ''acostó'' al niño Jesús en un pesebre, acción tierna de cuidado maternal. En Mr 6:39, Jesús ordena a los discípulos hacer que la multitud se recline en grupos. Lc 12:37 promete que el señor ''los hará recostarse'' a la mesa y él mismo les servirá, invirtiendo radicalmente los roles sociales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62187, 'spa', 'Gritar, dar alaridos', 'Gritar fuertemente, chillar con fuerza súbita. El prefijo ἀνά intensifica κράζω, produciendo un grito que estalla hacia arriba. Tres de cinco apariciones neotestamentarias involucran confrontación demoníaca (Mr 1:23, Lc 4:33, Lc 8:28). Los demás usos describen el grito de los discípulos aterrados y el clamor de la multitud.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62188, 'spa', 'Examinar cuidadosamente, discernir o evaluar, especialmente realidades espiritua', 'Examinar cuidadosamente, discernir o evaluar, especialmente realidades espirituales y afirmaciones de verdad. Los bereanos examinaban las Escrituras diariamente para verificar la enseñanza de Pablo (Hechos 17:11). En 1 Corintios 2:14-15, el hombre ''natural'' no puede discernir las cosas espirituales, mientras que el espiritual examina todas las cosas. También se usa para evaluar alimentos del mercado sin hacer preguntas de conciencia (1 Corintios 10:25, 27). El español ''discernir'' y ''examinar'' capturan este sentido evaluativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62190, 'spa', 'Interrogar o investigar judicialmente — un examen legal formal', 'Interrogar o investigar judicialmente — un examen legal formal. Pilato examinó formalmente a Jesús y no halló culpa (Lucas 23:14); los apóstoles fueron interrogados por el Sanedrín (Hechos 4:9); Félix ordenó a los acusadores que examinasen a Pablo (Hechos 24:8); Herodes interrogó a los guardias tras la fuga de Pedro (Hechos 12:19). El español ''interrogar'' y ''examinar'' reflejan el registro forense inherente a este sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62193, 'spa', 'Juzgar, pedir cuentas o someter a autoridad evaluativa', 'Juzgar, pedir cuentas o someter a autoridad evaluativa. Pablo declara que poco le importa ser ''juzgado'' por los corintios o por tribunal humano alguno (1 Corintios 4:3), pues quien verdaderamente lo examina es el Señor (1 Corintios 4:4). El español ''juzgar'' y el cambio de tono investigativo a evaluativo distinguen este sentido. El énfasis no recae en la búsqueda de hechos sino en el ejercicio de autoridad sobre otra persona.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62201, 'spa', 'Enderezarse o erguirse', 'Levantarse desde una postura encorvada o inclinada, ponerse erguido o alzar la cabeza. Lucas 13:11 describe a una mujer físicamente incapaz de enderezarse; Lucas 21:28 lo usa figuradamente para la expectativa confiada de la redención; Juan 8:7, 10 muestran a Jesús irguiéndose desde el suelo con gesto de autoridad serena.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62202, 'spa', 'Elevacion divina o celestial', 'Elevacion divina o celestial: ser recibido en el cielo, usado casi exclusivamente de la ascension de Cristo y actos divinos relacionados. Marcos 16:19 dice que Jesus ''fue recibido arriba en el cielo''; Hechos 1:2, 11, 22 repiten esto para el relato de la ascension; Hechos 10:16 lo usa para el lienzo de la vision que es retirado hacia arriba.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62204, 'spa', 'Levantar o recoger fisicamente', 'Levantar o recoger fisicamente: tomar objetos o llevar a alguien consigo. Pablo insta a los creyentes a ''tomar'' toda la armadura de Dios (Ef 6:13, 16), Esteban recuerda que Israel ''levanto'' el tabernaculo de Moloc (Hch 7:43), y Pablo pide a Timoteo que ''recoja a Marcos y lo traiga'' (2 Ti 4:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62206, 'spa', 'Embarque maritimo', 'Embarque maritimo: subir a alguien a bordo de una embarcacion. En Hechos 20:13-14, los companeros navegan adelante con la intencion de ''recoger a Pablo'' en Asos, y luego lo hacen en Mitilene. Este sentido nautico se distingue del levantamiento general.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62214, 'spa', 'consumir, destruir totalmente', 'El tema de consumir aparece: español ''los consuma'' y ''seáis consumidos,'' francés ''consumer,'' alemán preservando el griego. El deseo de los discípulos hace eco del fuego invocado por Elías (2 Reyes 1), mientras que la advertencia de Pablo retrata destrucción mutua. Ambos contextos implican destrucción total—ya sea por fuego divino o conflicto comunitario—enfatizando la completitud del consumo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62219, 'spa', 'partir, regresar', 'El tema de partida aparece: español ''vuelva'' (regresa) y ''partir,'' francés ''partir,'' alemán preservando el griego. El contexto de Lucas implica el regreso del amo a casa, mientras que Pablo describe la muerte como partir para estar con Cristo. La imagen militar/náutica de levantar campamento o zarpar encaja en ambos—movimiento de un lugar/estado a otro, ya sea viaje de regreso o travesía final.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62222, 'spa', 'Hacer recordar', 'Sentido activo causativo: traer algo a la atención de otra persona, hacerle recordar. En 1 Corintios 4:17 Pablo envía a Timoteo para que «les recuerde» a la iglesia la enseñanza de Pablo, y en 2 Timoteo 1:6 Pablo recuerda a Timoteo que avive el don de Dios. El paso del recuerdo pasivo al estímulo activo se marca claramente en el sistema de voces del griego.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62224, 'spa', 'Recordar, acordarse', 'Sentido medio-pasivo: traer algo a la propia memoria, rememorar o acordarse. Es el uso más frecuente (4 de 6 ocurrencias). En Marcos 14:72 Pedro recuerda la palabra de Jesús sobre la negación; en Hebreos 10:32 se insta a los creyentes a recordar los días anteriores de perseverancia. El español «recordando» y «acordarse» reflejan este acto reflexivo de recuperación de la memoria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62228, 'spa', 'Remembranza litúrgica activa', 'Traer deliberadamente a la memoria a una persona o acontecimiento, especialmente en el culto. Las cuatro apariciones neotestamentarias se agrupan en torno al memorial ritual: la Cena del Señor (''haced esto en memoria de mí'', Lucas 22:19; 1 Corintios 11:24-25) y el recordatorio sacrificial de los pecados (Hebreos 10:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62231, 'spa', 'Ananias esposo de Safira, miembro de la iglesia primitiva de Jerusalen que consp', 'Ananias esposo de Safira, miembro de la iglesia primitiva de Jerusalen que conspiro con su esposa para retener parte de la venta de un terreno mientras afirmaba entregar todo. Pedro expuso el engano como una mentira al Espiritu Santo, y Ananias cayo muerto de inmediato (Hch 5:1-5). Este episodio se convirtio en un paradigma solemne del juicio divino contra la deshonestidad dentro de la comunidad del pacto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62236, 'spa', 'Descanso, reposo', 'Descanso, reposo, cesación de actividad que trae verdadero refrigerio al cuerpo o al espíritu. Jesús lo promete a los agobiados (Mt 11:29). El espíritu inmundo de Mt 12:43/Lc 11:24 vaga buscando este descanso sin hallarlo. Apocalipsis lo emplea en dos direcciones opuestas: adoración incesante (Ap 4:8) y tormento sin fin (Ap 14:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62237, 'spa', 'Cesar la actividad y tomar descanso uno mismo — el uso intransitivo medio/pasivo', 'Cesar la actividad y tomar descanso uno mismo — el uso intransitivo medio/pasivo que describe reposo o respiro personal. Jesus dice a los discipulos ''Venid aparte y descansad un poco'' (Mr 6:31), y en Getsemani dice con triste ironia, ''Dormid ya y descansad'' (Mt 26:45).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62239, 'spa', 'Refrescar o dar descanso a otro — el sentido activo causativo, donde una persona', 'Refrescar o dar descanso a otro — el sentido activo causativo, donde una persona restaura a otra. La gran invitacion de Mt 11:28, ''Yo os hare descansar'', es el paradigma. Pablo elogia a la casa de Estefanas porque ''refrescaron mi espiritu'' (1 Co 16:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62242, 'spa', 'Ser refrescado, recibir descanso — el perfecto pasivo que indica refrigerio comp', 'Ser refrescado, recibir descanso — el perfecto pasivo que indica refrigerio completado recibido de otro. El espiritu de Tito ''ha sido refrescado'' por los corintios (2 Co 7:13), y el amor de Filemon ''ha refrescado los corazones de los santos'' (Flm 1:7). Este matiz resultativo y estativo se distingue del dar activo o del descansar voluntario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62248, 'spa', 'Enviar, remitir', 'Enviar arriba o remitir una persona o caso a otra autoridad, o devolver. El prefijo ἀνά implica movimiento ascendente o de retorno dentro de una cadena jurisdiccional. Pilato envía a Jesús a Herodes (Lc 23:7), quien lo devuelve (Lc 23:11). Festo remite a Pablo al emperador (Hch 25:21) y Pablo devuelve a Onésimo a Filemón (Flm 1:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62249, 'spa', 'lisiado, discapacitado', 'La discapacidad es consistente: español ''lisiados'' y ''a lisiados,'' francés ''estropié'' (mutilado), alemán preservando el griego. Ambos versículos pertenecen a la misma parábola que contrasta la hospitalidad mundana basada en reciprocidad con la generosidad del reino hacia los marginados. Los lisiados representan a quienes son excluidos de reuniones sociales convencionales pero específicamente incluidos en el banquete del reino de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62250, 'spa', 'Reclinarse (a la mesa), recostarse', 'Reclinarse (a la mesa), recostarse. Asumir la postura antigua de comer recostado sobre un costado junto a una mesa baja. Se usa para las multitudes que se acomodan en las alimentaciones milagrosas (Mt 15:35; Mr 6:40; 8:6), los invitados que toman su lugar en los banquetes (Lc 11:37; 14:10; 17:7), los discipulos en la Ultima Cena (Lc 22:14; Jn 13:12), y especificamente del discipulo amado que se recuesta contra el pecho de Jesus (Jn 13:25; 21:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62256, 'spa', 'Llenar, cumplir, completar', 'Llenar una deficiencia, cumplir una profecía o completar lo que está incompleto. El verbo conlleva un sentido inherente de hacer íntegro lo que era parcial. En Mateo 13:14 denota cumplimiento profético — el español «cumpliréis» apunta a la consumación de la Escritura. En 1 Corintios 14:16 uno «ocupa el lugar» del que no entiende, mientras que en 1 Corintios 16:17 se usa para suplir una ausencia personal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62262, 'spa', 'Moralmente indefensible', 'Apareciendo en dos pasajes cruciales de Romanos, este sentido describe la condición moral humana tras encontrar revelación clara. La palabra tiene un filo forense: no es meramente que las excusas sean débiles, sino que literalmente no existen. Pablo la usa para desmantelar tanto la indiferencia pagana (Rom 1:20) como la hipocresía religiosa (Rom 2:1), mostrando que el conocimiento de la verdad crea responsabilidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62264, 'spa', 'Encender fuego', 'Ambas ocurrencias neotestamentarias involucran fuego y sus efectos. El Jesús de Lucas anhela que el fuego ya esté encendido—probablemente refiriéndose al juicio o la obra transformadora del Espíritu. Santiago usa el mismo verbo para la capacidad de la lengua de encender conflicto destructivo. Las formas españolas fue-encendido y enciende capturan tanto el pasivo (fue encendido) como el activo (enciende), mostrando la flexibilidad del verbo al describir ignición.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62266, 'spa', 'Incitar multitudes', 'Ambos usos evangélicos involucran a líderes religiosos manipulando multitudes durante el juicio de Jesús. El verbo captura el acto deliberado de agitar personas hacia una acción particular—en este caso, demandar crucifixión. Las formas alemanas Ἀνασείει y ἀνέσεισαν preservan la distinción entre presente (Él alborota) y aoristo (ellos alborotaron), mostrando esto como tanto una táctica continua como un acto histórico específico durante la Pasión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62268, 'spa', 'Alzar hacia arriba', 'Las dos ocurrencias muestran tanto rescate literal (sacar de un pozo) como retiro visionario (alzar de vuelta al cielo). El ejemplo de Lucas usa el verbo en un dilema hipotético del sábado, mientras Hechos describe la conclusión de la visión de Pedro en la azotea. El alemán pasivo ἀνεσπάσθη (fue alzado) en Hechos contrasta con el futuro activo ἀνασπάσει (sacará) en Lucas, mostrando el rango del verbo al describir movimiento vertical.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62269, 'spa', 'Resurrección corporal de entre los muertos, el levantamiento escatológico de per', 'Resurrección corporal de entre los muertos, el levantamiento escatológico de personas fallecidas a la vida. Este es el uso abrumadoramente dominante en el Nuevo Testamento (41 de 42 apariciones). Todos los idiomas testigos convergen en un término dedicado único (resurrección). Pasajes clave incluyen la controversia con los saduceos (Mt 22:23-31), Pablo en Atenas (Hch 17:18) y la gran exposición de 1 Co 15.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62270, 'spa', 'Un surgir figurado en destino o fortuna, distinto de la resurrección corporal', 'Un surgir figurado en destino o fortuna, distinto de la resurrección corporal. La profecía de Simeón en Lc 2:34 declara al niño Cristo ''puesto para caída y levantamiento (ἀνάστασις) de muchos en Israel''. El español ''levantamiento'' captura el matiz no resurreccional, apuntando a una inversión más amplia de condición en vez de un regreso de la muerte.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62271, 'spa', 'Causar trastorno', 'Denota causar disrupción, conmoción o subversión, ya sea del orden social o de la paz espiritual. La acusación tesalonicense, aunque hostil, capta el impacto revolucionario del cristianismo: un movimiento que trastorna los patrones establecidos. El cargo contra Pablo lo presenta como alborotador, acusación que él redirige hacia los falsos maestros que «perturban» a los gálatas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62274, 'spa', 'Conducirse, vivir', 'Conducirse, comportarse o vivir de manera habitual: un uso distintivo de la voz media en el griego koiné que describe el modo de vida característico de una persona, no una acción aislada. Pablo declara que se condujo (ἀνεστράφημεν) en el mundo con sinceridad piadosa (2 Co 1:12), y se exhorta a los creyentes a conducirse (ἀναστράφητε) dignamente en la casa de Dios (1 Ti 3:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62276, 'spa', 'Regresar, volver', 'Regresar o volver a un lugar anterior: el sentido más antiguo y literal de dar la vuelta físicamente. Los oficiales regresaron (ἀνέστρεψαν) al concilio tras encontrar la prisión vacía (Hch 5:22), y Santiago cita a Amós donde el Señor promete «volveré» (ἀναστρέψω) para reedificar el tabernáculo caído de David (Hch 15:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62283, 'spa', 'Conducta, manera de vivir', 'Conducta, manera de vivir. La forma habitual de vida, patron de comportamiento o conducta tal como la observan los demas y la evaluan eticamente. Se usa para referirse a las antiguas costumbres pecaminosas (Ga 1:13, Ef 4:22), la vida cristiana ejemplar (1 Ti 4:12, 1 P 3:1-2), y el patron de vida de lideres dignos de imitar (He 13:7). El plural en He 13:7 no indica un sentido distinto, sino la forma acumulativa de toda una vida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62288, 'spa', 'Salir (del sol)', 'La salida literal e intransitiva del sol o de la luz del día sobre el horizonte. Es el uso más frecuente (6 de 9 apariciones), presente en parábolas donde el sol abrasador sale y marchita las plantas sin raíz (Mt 13:6; Mr 4:6), en el relato de Marcos sobre las mujeres que llegan al sepulcro al amanecer (Mr 16:2), y en la observación meteorológica de Lucas sobre nubes que se levantan por el occidente (Lc 12:54).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62290, 'spa', 'Amanecer (figurado)', 'Una extensión figurada donde la luz «amanece» sobre personas que están en tinieblas espirituales. Se encuentra únicamente en Mt 4:16, donde Mateo cita Isaías 9:1-2 para anunciar que la luz mesiánica ha resplandecido sobre Galilea. El español amaneció capta el cambio metafórico de lo astronómico a lo teológico, marcando el ministerio de Jesús como cumplimiento de la promesa profética.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62291, 'spa', 'Surgir (de un linaje)', 'Se usa para referirse a una persona que surge o brota de un linaje tribal, aplicado en He 7:14 a la descendencia de Cristo de Judá en vez de Leví. El español ha surgido transmite la metáfora botánica de un brote que emerge de una raíz, evocando la imaginería mesiánica del «renuevo» que recorre los profetas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62294, 'spa', 'Hacer salir (causativo)', 'El sentido causativo: Dios activamente hace salir el sol sobre las personas. En Mt 5:45, Jesús enseña que el Padre «hace salir su sol» tanto sobre malos como sobre buenos. El español hace salir destaca la agencia transitiva, distinguiendo este uso de los sentidos intransitivos. Solo aquí el verbo toma un sujeto personal divino que ordena el movimiento del astro celeste.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62295, 'spa', 'Presentar para evaluación', 'Ambos usos involucran presentar asuntos a autoridades para valoración. Festo busca el consejo de Agripa sobre el complejo caso de Pablo, mientras Pablo busca la validación de los líderes de Jerusalén para su mensaje evangélico. La voz media sugiere inversión personal—no meramente reportar hechos sino someter algo personalmente significativo a la consideración de otro. Las formas alemanas ἀνέθετο y ἀνεθέμην preservan estas distinciones en voz media.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62296, 'spa', 'El oriente como punto cardinal o region geografica, el lugar donde sale el sol', 'El oriente como punto cardinal o region geografica, el lugar donde sale el sol. Mateo lo usa repetidamente para el origen y viaje de los magos (Mt 2:1, 2, 9), para la reunion escatologica de oriente a occidente (Mt 8:11; 24:27), y en la imageneria apocaliptica del Apocalipsis (Ap 16:12; 21:13). El espanol ''oriente'' lo traduce uniformemente como termino direccional sencillo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62297, 'spa', 'El acto o fenomeno de salir o aparecer, especificamente la salida de un cuerpo c', 'El acto o fenomeno de salir o aparecer, especificamente la salida de un cuerpo celeste o una aparicion semejante al alba, que a menudo conlleva significado mesianico o cosmico. En Lucas 1:78, el Benedictus de Zacarias declara que ''la ἀνατολή desde lo alto nos visitara'', donde la palabra evoca al ''Rebrote'' o ''Aurora de lo alto'', titulo cargado de resonancia profetica de Jeremias 23:5 y Zacarias 3:8 (LXX). Apocalipsis 7:2 describe al angel que asciende desde donde sale el sol.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62299, 'spa', 'Derribar con fuerza', 'Denota un vuelco enérgico, tanto de objetos físicos como de destrucción metafórica. La acción de Jesús en el templo es agresiva: vuelca las mesas físicamente para interrumpir el comercio corrupto. Las epístolas pastorales lo aplican al daño doctrinal: una enseñanza falsa que hace zozobrar la fe como un barco que naufraga.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62300, 'spa', 'Criar y educar', 'Designa el proceso integral de crianza: alimentar, proteger y educar. La doble crianza de Moisés —nacimiento hebreo, educación egipcia— moldeó su papel singular. La formación de Pablo en Jerusalén bajo Gamaliel estableció sus credenciales fariseas. La voz media en Hechos 7:21 subraya la inversión personal de la hija del faraón al adoptarlo como hijo propio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62301, 'spa', 'Aparecer, manifestarse', 'Lucas usa el verbo para la manifestación esperada del reino—una aparición que la gente anticipaba inminentemente cuando Jesús se acercaba a Jerusalén. Hechos emplea el mismo verbo más literalmente para una isla que aparece en el horizonte durante la navegación. El francés apparaître y el español aparecer funcionan para ambos contextos: la aparición del reino y el avistamiento de tierra. Esto muestra cómo la manifestación visual une lo literal y lo teológico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62302, 'spa', 'Conducir o llevar fisicamente a alguien hacia un lugar mas alto', 'Conducir o llevar fisicamente a alguien hacia un lugar mas alto. Se usa cuando Jesus lleva a sus tres discipulos mas cercanos a un monte alto para la Transfiguracion (Mt 17:1; Mr 9:2), y en la ascension de Cristo al cielo (Lc 24:51). El espanol distingue este sentido del cultual con ''llevar arriba'', mientras que el griego mantiene el mismo verbo para ambos, sugiriendo que el ascenso fisico ya era metaforico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62303, 'spa', 'Presentar un sacrificio u ofrenda a Dios, ya sean las ofrendas literales de anim', 'Presentar un sacrificio u ofrenda a Dios, ya sean las ofrendas literales de animales del antiguo pacto o los sacrificios espirituales de alabanza y buenas obras bajo el nuevo. El espanol ''ofrezcamos'' capta la direccionalidad ascendente de la presentacion cultual. Pasajes clave: Heb 7:27 (la ofrenda de Cristo de una vez para siempre), 1 Pe 2:5 (los creyentes como sacerdocio santo que ofrece sacrificios espirituales).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62305, 'spa', 'Cargar o llevar pecados sobre si mismo en expiacion sustitutiva', 'Cargar o llevar pecados sobre si mismo en expiacion sustitutiva. En Heb 9:28, Cristo ''llevo los pecados de muchos'', haciendo eco de Isaias 53:12, y en 1 Pe 2:24 ''llevo nuestros pecados en su cuerpo sobre el madero''. El espanol cambia a ''llevar/llevo'', marcando una clara ruptura semantica con el sacrificial ''ofrecer''. Este sentido fusiona el movimiento ascendente de la cruz con el peso teologico del pecado vicario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62311, 'spa', 'Retirarse, apartarse', 'Retirarse, apartarse. Retirarse deliberadamente de un lugar, generalmente para evitar peligro, hostilidad o atencion no deseada, o para buscar privacidad y soledad. Concentrado en el Evangelio de Mateo (10 de las 14 apariciones en el NT), el verbo narra partidas estrategicas: los magos evitando a Herodes (Mt 2:12), la sagrada familia huyendo a Egipto (Mt 2:13-14) y las repetidas retiradas de Jesus frente a la oposicion (Mt 4:12; 12:15; 14:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62319, 'spa', 'Andres', 'Andres. El nombre propio Ανδρέας, que designa al apostol hermano de Simon Pedro, pescador de Betsaida (Jn 1:44). Las 13 apariciones en el NT se refieren a este unico individuo. Aparece en los relatos del llamamiento (Mt 4:18; Mr 1:16; Jn 1:40), las listas apostolicas (Mt 10:2; Mr 3:18; Lc 6:14; Hch 1:13) y varios episodios propios del Evangelio de Juan donde sirve como mediador que trae personas a Jesus.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62326, 'spa', 'Inacusable, irreprochable', 'Que no puede ser acusado formalmente; más allá de toda imputación legal. El matiz forense distingue esta palabra del más general ἄμεμπτος: ἀνέγκλητος implica específicamente que ningún acusador podría presentar un caso con éxito. Pablo lo aplica escatológicamente — los creyentes serán presentados intachables ante Cristo (1 Cor 1:8, Col 1:22). Las Pastorales lo establecen como requisito concreto para el liderazgo eclesial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62330, 'spa', 'Más tolerable', 'Más soportable, más tolerable — usado exclusivamente en forma comparativa (ἀνεκτότερον) en los pronunciamientos de juicio escatológico de Jesús. El patrón es consistente en Mateo 10:15, 11:22, 11:24, Marcos 6:11 y Lucas 10:12: rechazar a los testigos del evangelio acarrea un destino peor que el de Sodoma. Toda la tradición de traducción lo rinde en forma comparativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62333, 'spa', 'Movimiento natural del aire, que abarca desde una brisa hasta un vendaval violen', 'Movimiento natural del aire, que abarca desde una brisa hasta un vendaval violento. Domina las narrativas sinópticas donde Jesús calma la tempestad y el viento le obedece (Mt 8:26; Mr 4:39; Lc 8:24). Se usa figuradamente para la inestabilidad doctrinal (Ef 4:14) y para el que duda, zarandeado como ola por el viento (Stg 1:6). En Ap 7:1, cuatro ángeles retienen los cuatro vientos de la tierra como imagen apocalíptica de contención cósmica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62340, 'spa', 'Inescrutable divino', 'Ambos usos paulinos aplican este término a realidades divinas que exceden la capacidad humana de comprensión. Romanos se enfoca en los planes soberanos de Dios en la historia de salvación, mientras Efesios resalta la riqueza inagotable de Cristo. El cambio español de inescrutable a inexplorables sugiere tanto inescrutabilidad (no puede ser escrutado) como inexplorable (no puede ser completamente mapeado). Esto no es oscurantismo sino reconocimiento humilde de lo infinito.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62342, 'spa', 'Carácter irreprensible', 'Denota un carácter intachable: no perfección absoluta, sino ausencia de acusación legítima. Los líderes eclesiales deben tener una reputación más allá de toda crítica para no desacreditar el evangelio. Las viudas inscritas deben ser reconocidas por su vida ejemplar. El encargo a Timoteo es escatológico: mantener una conducta irreprochable hasta el retorno de Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62343, 'spa', 'Subir o regresar', 'Indica movimiento ascendente o retorno a una ubicación previa. La nota geográfica de Juan sobre Jesús subiendo al monte prepara la escena para la multiplicación de los panes. La cronología precisa de Pablo usa este verbo para sus viajes a Jerusalén: su primera visita demorada (Gálatas 1:17) y su posterior consulta con Pedro (1:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62344, 'spa', 'Alivio, descanso', 'Aflojamiento, alivio o relajación de presión — ya sea restricción física, angustia emocional o aflicción externa. La metáfora raíz es la de una tensión que se libera. Félix ordena que Pablo reciba ἄνεσις en su encarcelamiento, es decir, custodia relajada con libertad para recibir visitas (Hch 24:23). Pablo describe dos veces su incapacidad de hallar ἄνεσις para su espíritu (2 Cor 2:13, 7:5), y 2 Tesalonicenses 1:7 lo proyecta escatológicamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62345, 'spa', 'Interrogatorio judicial', 'Ambos usos en Hechos involucran el intento del tribuno romano de descubrir por qué la multitud judía se amotinó contra Pablo. El examen previsto implica azotes—tortura diseñada para extraer la verdad de los no ciudadanos. Cuando Pablo revela su ciudadanía, la situación legal se invierte: lo que era un examen permisible se convierte en un potencial asalto. Los infinitivos ἀνετάζειν (examinar) y ἀνετάζεσθαι (ser examinado) muestran tanto el propósito del viaje como su resultado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62346, 'spa', 'Ausencia o carencia', 'El término aparece en las tres ocurrencias neotestamentarias con el sentido de «sin» o «aparte de». Jesús lo emplea para expresar la providencia divina que no deja nada inadvertido (Mateo 10:29), mientras que Pedro lo aplica a la conducta cristiana que obra con independencia de ciertas acciones: fe testimoniada sin palabras y hospitalidad ejercida sin quejas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62348, 'spa', 'Encontrar tras búsqueda', 'Ambas ocurrencias involucran encontrar personas en ubicaciones específicas. El descubrimiento de los pastores cumple el anuncio angelical—buscan y encuentran exactamente lo que fue prometido. El grupo de Pablo descubre la comunidad cristiana en Tiro, permitiendo comunión y advertencia profética. Los participios ἀνευρόντες (habiendo encontrado) y el aoristo ἀνεῦραν (encontraron) muestran tanto el propósito del viaje (encontrar como meta) como su cumplimiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62349, 'spa', 'El sentido dominante en el NT', 'El sentido dominante en el NT: aguantar a alguien o algo percibido como necio, tedioso o desagradable. El español ''soportar'' captura bien este matiz de paciencia resignada. La triple reprensión de Jesús en los Sinópticos (Mateo 17:17, Marcos 9:19, Lucas 9:41) muestra la paciencia divina con discípulos incrédulos. Pablo lo aplica a tolerar falsos maestros (2 Corintios 11:4), a escuchar una apelación (Hechos 18:14) y a pedir a los corintios que le soporten un poco de insensatez (2 Corintios 11:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62352, 'spa', 'Un matiz más cercano a la resistencia firme bajo la aflicción, donde el énfasis ', 'Un matiz más cercano a la resistencia firme bajo la aflicción, donde el énfasis pasa de tolerar personas a sostenerse bajo la adversidad sin ceder. Pablo en 1 Corintios 4:12 enumera ''soportamos'' junto con ser perseguidos e injuriados, y en 2 Tesalonicenses 1:4 elogia la paciente resistencia de los creyentes en medio de persecuciones. El español emplea ''soportar'' y ''resistir'' para capturar esta dimensión de aguante activo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62360, 'spa', 'Lo propio y decoroso', 'Las tres ocurrencias involucran lo «conveniente» o «propio» en la vida y conducta cristiana. Pablo hace referencia a lo apropiado en el habla (Efesios 5:4), en las relaciones matrimoniales (Colosenses 3:18) y en el ejercicio de la autoridad apostólica (Filemón 1:8). El trasfondo clásico de alcanzar un estándar adecuado informa el uso neotestamentario del término.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62362, 'spa', 'varón, hombre', 'Un ser humano adulto de sexo masculino, un hombre distinguido de una mujer o un niño — el sentido dominante con 202 ocurrencias. Se usa en vocativos (ἄνδρες ἀδελφοί, «varones hermanos», Hch 1:16), en descripción narrativa (Lc 5:8, «Simón Pedro, hombre pecador») y en referencia general a personas masculinas. El español alterna entre ''varón'' y ''hombre'' según el registro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62367, 'spa', 'esposo, marido', 'Esposo, un hombre casado en relación con su mujer — 13 ocurrencias concentradas en las Epístolas y Juan. La teología matrimonial de Pablo en Ef 5:22-25 y Ro 7:2-3 depende de ἀνήρ como ''esposo'', y el diálogo de la samaritana con Jesús gira en torno a «has tenido cinco maridos» (Jn 4:17-18). El español distingue con ''marido'' y ''esposo'', vocabulario conyugal específico diferenciado de ''hombre''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62377, 'spa', 'persona, ser humano', 'Un ser humano de modo genérico, sin énfasis específico en el sexo masculino — una sola ocurrencia en Stg 1:20, donde «la ira del hombre no obra la justicia de Dios». Aquí ἀνήρ funciona de manera semejante a ἄνθρωπος, refiriéndose a cualquier persona y no específicamente a varones. La evidencia interlingüística es mixta: el español ''varón'' y el alemán ''Mann'' mantienen la especificidad masculina, pero el punto teológico es universal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62378, 'spa', 'Resistir, oponerse, hacer frente', 'Resistir, oponerse, hacer frente. Plantarse en oposicion a una fuerza, autoridad o adversario, manteniendose firme en lugar de ceder. El NT lo aplica a la confrontacion interpersonal (Pablo oponiendose a Pedro, Ga 2:11), la guerra espiritual (resistir al diablo, Stg 4:7; 1 P 5:9), la resistencia al testimonio apostolico (Hch 6:10; 13:8; 2 Ti 3:8; 4:15) y la rebelion contra el orden establecido por Dios (Ro 9:19; 13:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62388, 'spa', 'Flor o floración', 'Flor o brote de una planta, empleado figuradamente para la belleza efímera y la fragilidad de la vida humana. Santiago 1:10-11 la empareja con la hierba que perece bajo el sol; 1 Pedro 1:24 hace eco de Isaías comparando la carne mortal con hierba y su flor marchita. Un sentido botánico único con uso metafórico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62389, 'spa', 'Fuego de carbón', 'El uso deliberado de Juan de este término específico en ambas escenas que involucran a Pedro crea resonancia teológica. En el primer fuego de carbón, Pedro niega a Jesús tres veces; en el segundo, Jesús pregunta a Pedro tres veces si lo ama. El vocabulario preciso—no cualquier fuego, sino específicamente un fuego de carbón—sugiere que Juan quiere que los lectores conecten estos momentos. El calor que Pedro buscó en el primer fuego contrasta con la calidez relacional del segundo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62391, 'spa', 'complacientes de hombres', 'Ambos usos paulinos advierten a los esclavos contra el servicio realizado meramente cuando los amos están mirando—servicio ante los ojos dirigido al favor humano. La alternativa es servir como esclavos de Cristo, haciendo la voluntad de Dios desde el corazón. El compuesto ἀνθρωπάρεσκος combina ἄνθρωπος (humano) y ἀρέσκω (agradar), creando una palabra que diagnostica el peligro espiritual de actuar para audiencias humanas. La preocupación de Pablo es la autenticidad: no el servicio performativo sino el servicio genuino motivado por devoción a Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62392, 'spa', 'Humano, de la humanidad', 'Perteneciente a los seres humanos, característico de o limitado a la humanidad, en contraste con lo divino o sobrenatural. El español «humano/humana» captura fielmente este sentido. En 1 Co 2:13 Pablo contrasta la sabiduría humana con la enseñada por el Espíritu; en 1 Co 10:13 la tentación es «humana», es decir, dentro de la capacidad mortal de soportar; en Ro 6:19 habla «en términos humanos» por la debilidad de la audiencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62397, 'spa', 'Homicida', 'Aparece en contextos tanto de asesinato espiritual como literal. Jesús identifica a Satanás como el arquetípico ἀνθρωποκτόνος en Juan 8:44, mientras que 1 Juan 3:15 aplica el término a todo aquel que alberga odio, enseñando que el impulso homicida nace en el corazón. Las traducciones consistentes en diversas lenguas reflejan su significado inequívoco.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62398, 'spa', 'persona individual', 'Un ser humano individual o persona, ya sea nombrado o indefinido, distinto de Dios, ángeles o animales. Este sentido dominante (469 ocurrencias) abarca individuos específicos (Mt 9:9), personas indefinidas en parábolas (Mt 7:9) y el título cristológico «Hijo del Hombre». Todas las lenguas emplean su sustantivo primario de persona: español ''hombre'', francés ''homme'', alemán ''Mensch''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62401, 'spa', 'gente, humanidad', 'La gente colectivamente o la humanidad en general, frecuentemente en el plural οἱ ἄνθρωποι o en declaraciones genéricas en singular sobre la raza humana. Con 86 ocurrencias, este sentido aparece en contextos universalizadores: «para que vean vuestras buenas obras» (Mt 5:16), «mientras los hombres dormían» (Mt 13:25), «toda palabra ociosa que hablen los hombres» (Mt 12:36). El español emplea el plural ''hombres'' o ''personas''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62425, 'spa', 'Procónsul romano', 'Procónsul, el gobernador romano de una provincia senatorial, que ejercía la autoridad civil y judicial suprema dentro de su jurisdicción. Lucas demuestra cuidadosa exactitud histórica al usar este título: Sergio Paulo gobierna Chipre (Hch 13:7–8, 12) y Galión gobierna Acaya (Hch 18:12), ambas correctamente identificadas como provincias senatoriales. El plural ἀνθύπατοι en Hechos 19:38 es probablemente una referencia genérica al cargo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62426, 'spa', 'Soltar o desatar', 'Desatar, soltar o liberar algo que está físicamente sujeto. En Hechos 16:26 las cadenas de los prisioneros son desatadas por un terremoto; en Hechos 27:40 los marineros sueltan las anclas. Las traducciones al español como ''soltar/fueron-soltadas'' y las glosas participiales en otros idiomas apuntan a un acto concreto y físico de liberar lo que estaba atado o asegurado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62428, 'spa', 'manos sin lavar', 'Ambos usos en los Evangelios involucran disputas sobre tradiciones de pureza ritual. Los fariseos observan que los discípulos de Jesús comen con manos sin lavar, violando la tradición de los ancianos. Jesús responde distinguiendo la pureza moral interna de la limpieza ritual externa. El dativo plural ἀνίπτοις (con manos sin lavar) aparece en ambos relatos, mostrando cómo la controversia se centraba específicamente en las manos—el punto de contacto entre el cuerpo y el alimento que entraba en la boca.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62429, 'spa', 'levantarse, ponerse de pie', 'El sentido intransitivo físico básico: levantarse, ponerse de pie desde una posición sentada, reclinada o postrada. Es el uso más frecuente, presente en transiciones narrativas a lo largo de los Evangelios y Hechos. Jesús se levanta y parte (Mc 7:24), el sumo sacerdote se pone de pie en el juicio (Mt 26:62), y personas se levantan en respuesta a eventos. El español ''levantarse'' captura con exactitud este movimiento cotidiano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62432, 'spa', 'resucitar, volver a la vida', 'El sentido intransitivo de resurrección: resucitar de entre los muertos, volver a la vida. Central para la cristología neotestamentaria, aparece en las predicciones de la pasión de Jesús (Mc 8:31; 9:9-10; 9:31) y en las primeras proclamaciones kerygmáticas. El sujeto es la persona fallecida que resucita. El español ''resucitar'' explicita el peso teológico, mientras que otras lenguas mantienen el mismo verbo que el sentido físico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62435, 'spa', 'resucitar a otro', 'El sentido transitivo causativo aplicado a la resurrección: resucitar a alguien de entre los muertos. Aquí el sujeto —típicamente Dios— hace que una persona muerta vuelva a vivir. Jn 6 concentra cuatro usos cuando Jesús declara que el Padre resucitará a los creyentes en el último día (Jn 6:39-40, 44, 54). Pedro proclama que Dios resucitó a Jesús (Hch 2:24). El español emplea ''resucitar'' en su forma transitiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62436, 'spa', 'suscitar, levantar a prominencia', 'El sentido transitivo de levantar a una persona a prominencia, autoridad o acción — no de la muerte sino hacia un papel. Dios suscita un profeta como Moisés (Hch 3:22; 7:37), o figuras se levantan en el juicio (Mt 12:41; Lc 11:32 — los hombres de Nínive se levantarán en el juicio). El contexto del levirato en Mt 22:24 extiende esto a levantar descendencia para un hermano. El español ''levantar'' o ''suscitar'' cubre este sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62458, 'spa', 'Anás, sumo sacerdote', 'Anás, sumo sacerdote judío y patriarca de una dinastía sacerdotal. Las cuatro apariciones neotestamentarias se refieren al mismo individuo: el suegro de Caifás que ejercía autoridad entre bastidores en Jerusalén. Lucas 3:2 lo empareja con Caifás, Juan 18:13-24 lo sitúa en la audiencia preliminar de Jesús, y Hechos 4:6 lo nombra entre quienes interrogaron a los apóstoles.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62459, 'spa', 'Insensato, necio', 'Insensato, falto de entendimiento espiritual — describe a personas que deberían percibir la verdad pero no lo hacen. La construcción con alfa privativa (ἀ + νοητός) señala una mente que no se involucra adecuadamente. El español «insensatos» captura este sentido de carecer de juicio. Lucas 24:25 lo aplica a los discípulos que no comprendieron las Escrituras sobre el Mesías. Romanos 1:14 lo usa para los necios en contraste con los sabios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62462, 'spa', 'locura irracional', 'Lucas describe a líderes religiosos consumidos por furia irracional después de la sanidad de Jesús en el día de reposo—su ἄνοια es ira reactiva que no puede pensar con claridad. Pablo usa el sustantivo para predecir cómo la necedad de los falsos maestros eventualmente será expuesta. El genitivo ἀνοίας (de locura) en 2 Timoteo sugiere necedad como cualidad que se vuelve cada vez más evidente. El español distingue insensatez (necedad) de locura (demencia), permitiendo matices según el contexto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62463, 'spa', 'abrir (transitivo)', 'Uso activo y transitivo: un agente abre algo — una puerta, portón, boca, libro, sello u ojos. En Mt 2:11 los magos abren sus cofres; en Mt 5:2 Jesús abre su boca para enseñar; en Mt 13:35 las Escrituras se cumplen mediante parábolas que «abren» cosas ocultas. Este es el uso más frecuente, presente a lo largo de narrativas, parábolas y discursos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62466, 'spa', 'ser abierto (pasivo)', 'Uso pasivo: algo es abierto por agencia divina o externa. Cuando los cielos son «abiertos» en el bautismo de Jesús (Mt 3:16), o cuando Jesús promete «llamad, y se os abrirá» (Mt 7:7), la voz pasiva suele implicar a Dios como agente tácito — un pasivo teológico. Los ciegos reciben la vista cuando sus ojos «son abiertos» (Mt 9:30; 20:33), y en Apocalipsis los sellos «son abiertos» por el Cordero.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62468, 'spa', 'abierto, en estado abierto', 'Uso estativo o resultativo, típicamente un participio perfecto que indica que algo permanece en estado abierto. En Jn 1:51 Natanael verá «el cielo abierto» — no el evento de abrirse sino la condición permanente. Hch 10:11 describe un recipiente que desciende del «cielo abierto». Ro 3:13 cita al salmista: «Sepulcro abierto es su garganta», donde lo abierto es un estado persistente de corrupción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62487, 'spa', 'reedificar restaurando', 'El uso duplicado en Hechos 15:16 proviene de la estructura de la cita de la Septuaginta: ''Volveré y reedificaré el tabernáculo de David que ha caído; reedificaré sus ruinas.'' La repetición enfatiza la iniciativa divina y la completitud en la restauración. Jacobo aplica esta profecía de restauración davídica al debate sobre la inclusión de los gentiles, sugiriendo que la obra de reedificación de Dios involucra incorporar a todas las naciones en la casa restaurada de David.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62489, 'spa', 'El estado o práctica habitual de actuar sin consideración por la ley revelada de', 'El estado o práctica habitual de actuar sin consideración por la ley revelada de Dios — no simplemente ignorancia de estatutos legales sino rebelión moral deliberada. Se usa tanto para la maldad individual (Mateo 7:23, ''los que practicáis la iniquidad'') como para el mal escatológico colectivo (Mateo 24:12, donde la ἀνομία aumenta y el amor se enfría). El español ''iniquidad'' capta el peso profundamente moral, y no meramente legal, de este término, que en 2 Tesalonicenses 2:7 aparece como el ''misterio de la iniquidad'' ya operante en el mundo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62496, 'spa', 'Sin la Ley mosaica, sin Torah -- un descriptor relacional mas que moral para qui', 'Sin la Ley mosaica, sin Torah -- un descriptor relacional mas que moral para quienes estan fuera del marco del pacto. El cuadruple uso de Pablo en 1 Corintios 9:21 es estrategico: se hace ''como sin ley'' para ganar a los ''sin ley'', anadiendo cuidadosamente ''no estando sin la ley de Dios, sino bajo la ley de Cristo''. El espanol ''sin ley'' preserva el tono neutral y descriptivo que distingue este sentido del peyorativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62497, 'spa', 'Moralmente sin ley, inicuo o impio, que describe a personas que transgreden la l', 'Moralmente sin ley, inicuo o impio, que describe a personas que transgreden la ley divina o moral. Se usa sustantivadamente para criminales y malhechores: Jesus es ''contado con los inicuos'' (Mr 15:28; Lc 22:37), y Pablo nombra al adversario escatologico ''el Inicuo'' (2 Ts 2:8). El espanol ''inicuo'' capta esa desafiante rebeldia moral activa contra la ley de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62503, 'spa', 'sin ley mosaica', 'El uso duplicado de Romanos 2:12 establece un principio simétrico: aquellos sin ley (gentiles) enfrentan juicio apropiado a su posición, así como aquellos con ley (judíos). Pablo no está diciendo que la ausencia de ley es aceptable, sino que Dios juzga justamente según qué revelación han recibido las personas. El adverbio ἀνόμως describe no anarquía moral sino estatus de pacto—estar fuera de la comunidad del pacto mosaico, sin acceso a la revelación escrita de Dios en la Torá.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62504, 'spa', 'Restaurar y enderezar', 'Se emplea en contextos de sanidad literal, restauración profética y exhortación espiritual. En Lucas 13:13, Jesús «enderezó» (ἀνωρθώθη) físicamente a una mujer encorvada durante dieciocho años. Hechos 15:16 cita la promesa de Amós de «restaurar» la tienda caída de David, interpretada como la inclusión de los gentiles. Hebreos 12:12 llama al «fortalecimiento» espiritual en medio de las pruebas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62505, 'spa', 'Impío, profano', 'Ambos usos pastorales listan a los ἀνόσιοι entre catálogos de pecadores. En 1 Timoteo, están emparejados con βέβηλοι (profanos)—juntos describiendo personas que violan tanto límites sagrados divinos como humanos. La ley existe para restringir a tales personas. En 2 Timoteo, la impiedad aparece en el deterioro del panorama moral de los últimos días. El nominativo plural ἀνόσιοι describe personas caracterizadas por desprecio hacia lo sagrado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62506, 'spa', 'Clemencia divina', 'Romanos usa ἀνοχή para describir la paciencia de Dios al retener el juicio inmediato. En 2:4, esta clemencia debería llevar a las personas al arrepentimiento, no a la presunción. En 3:26, la clemencia que pasó por alto pecados anteriores ahora se vindica mediante la obra expiatoria de Cristo—mostrando que Dios fue justo incluso cuando parecía pasar por alto el pecado. El genitivo ἀνοχῆς sugiere una cualidad o período de clemencia—una temporada de paciencia paciente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62508, 'spa', 'Intercambio por el alma', 'Ambos usos evangélicos presentan la misma pregunta retórica en la enseñanza de Jesús sobre los costos del discipulado: ¿Qué intercambio podría alguien ofrecer por su alma? La respuesta implícita es nada—el valor del alma excede cualquier comercio posible. El acusativo ἀντάλλαγμα sugiere el objeto ofrecido en intercambio. El punto de Jesús es que ninguna cantidad de ganancia mundana compensa la pérdida del verdadero yo ante Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62510, 'spa', 'Retribuir, recompensar', 'El sentido activo de retribuir, recompensar o devolver en correspondencia, sea para bien o para mal. Romanos 12:19 y Hebreos 10:30 citan a Dios como quien retribuirá la venganza. En 2 Tesalonicenses 1:6, Dios retribuye tribulación a quienes afligen a los creyentes. En 1 Tesalonicenses 3:9, Pablo pregunta qué acción de gracias puede «devolver» a Dios, usando el mismo verbo para la retribución agradecida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62512, 'spa', 'Ser recompensado', 'El sentido pasivo: ser retribuido o recibir recompensa. En Lucas 14:14 Jesús asegura que quien invite a los pobres, lisiados y ciegos — aquellos que no pueden devolver el favor — «será recompensado» (ἀνταποδοθήσεται) en la resurrección. Romanos 11:35 plantea la pregunta retórica de si alguien le ha dado primero a Dios «para que le sea retribuido».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62516, 'spa', 'Recompensa o retribución', 'Lucas usa ἀνταπόδομα para la recompensa escatológica que espera a quienes sirven sin esperar reciprocidad terrenal. Romanos emplea la misma palabra para la retribución divina sobre quienes tropiezan—sus bendiciones convirtiéndose en su juicio. La flexibilidad del sustantivo le permite describir la justicia de Dios en ambas direcciones: recompensar a los fieles y retribuir a los rebeldes. El acusativo ἀνταπόδομα y nominativo revelan su uso versátil.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62518, 'spa', 'Replicar, contestar', 'Hacer una réplica que argumenta en contra o contradice, particularmente en un contexto donde tal respuesta puede ser presuntuosa o fútil. Ambas ocurrencias del Nuevo Testamento enfatizan la incapacidad o impropiedad de replicar—Lucas 14:6 describe a los oponentes de Jesús incapaces de refutar su razonamiento, mientras Romanos 9:20 reprende la presunción humana al disputar con Dios. La estructura compuesta (ἀντα- + ἀποκρίνομαι) comunica oposición verbal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (62519, 'spa', 'Aferrarse con devoción', 'Ser devoto de, adherirse o mantenerse firme en lealtad. En los dichos sobre los «dos señores» (Mateo 6:24; Lucas 16:13), describe el apego exclusivo al señor elegido. Tito 1:9 requiere que los ancianos se aferren a la sana doctrina. El español ''aferrarse/adherirse'' y el francés ''s''attacher'' subrayan la cualidad tenaz de esta devoción: no mero acuerdo, sino compromiso persistente.');